const [onDismiss, setOnDismiss] = useState(false) // not on a solid alert either
const [banner, setBanner] = useState(false)

<Alert
  color={color}
  variant={variant}
  title={title ? "Scheduled maintenance" : undefined}
  description={description ? "We'll be offline 2 - 4 AM UTC on July 14 while we upgrade our database." : undefined}
  indicator={indicator}
  actions={actions ? (
    <>
      <Button color="primary" variant="soft" pill>Set reminder</Button>
      <Button color="primary" variant="solid" pill>View status</Button>
    </>
  ) : undefined}
  actionsPlacement={actionsPlacement}
  mobileActions={mobileActions}
  onDismiss={onDismiss ? () => {} : undefined}
