const today = DateTime.local()
const [date, setDate] = useState<DateTime | null>(null)
const [variant, setVariant] = useState("outline") // or "soft"
const [size, setSize] = useState("md") // "3xs" to "3xl"
const [pill, setPill] = useState(false)
const [mode, setMode] = useState("dd/mm/yyyy") // or "mm/dd/yyyy", "yyyy/mm/dd"
const [separator, setSeparator] = useState(".") // or "/", "-"
const [timeMode, setTimeMode] = useState(undefined) // or "HH:MM", "HH:MM:SS", "HH:MM AA"
const [dateTimeSeparator, setDateTimeSeparator] = useState(", ") // or " "; with a time
const [timeStep, setTimeStep] = useState(0) // the arrow keys' step on a time segment, 0 for none; with a time
const [limits, setLimits] = useState(false) // min and max, 30 days around today
const [clearable, setClearable] = useState(true)
const [invalid, setInvalid] = useState(false)
const [disabled, setDisabled] = useState(false)

// Desktop: wide enough for the date, and for its time
<div className={!timeMode ? "w-[200px]" : timeMode === "HH:MM" ? "w-[260px]" : "w-[300px]"}>
  <DateInput
    value={date}
    onChange={setDate}
    variant={variant}
    size={size}
    pill={pill}
    mode={mode}
    separator={separator}
    timeMode={timeMode}
    dateTimeSeparator={dateTimeSeparator}
    timeStep={timeStep}
    min={limits ? today.minus({ days: 30 }).startOf("day") : undefined}
    max={limits ? today.plus({ days: 30 }).endOf("day") : undefined}
    clearable={clearable}
    invalid={invalid}
    disabled={disabled}
  />
</div>

// Phone: the date is the value of a row, which is its frame
<FieldGroup>
  <Field row label="Date">
    <DateInput
      value={date}
      onChange={setDate}
      mode={mode}
      separator={separator}
      timeMode={timeMode}
      dateTimeSeparator={dateTimeSeparator}
      timeStep={timeStep}
      min={limits ? today.minus({ days: 30 }).startOf("day") : undefined}
      max={limits ? today.plus({ days: 30 }).endOf("day") : undefined}
      clearable={clearable}
      disabled={disabled}
    />
  </Field>
</FieldGroup>

