const allows = ([start, end]: DateRange) =>
  !(min && start < min.startOf("day")) &&
  !(max && end > max.endOf("day")) &&
  !(maxRangeDays != null && end.startOf("day") > start.startOf("day").plus({ days: maxRangeDays - 1 }))
const periodOptions = dayShortcuts.map(({ label, getDateRange }) => ({ value: label, label, disabled: !allows(getDateRange()) }))
