const scaleMarks = [0, 25, 50, 75, 100].map((value) => ({ value, label: String(value) }))
// The slider is named after what it sets: a value in percent, in dollars or bare; a range or tiers of them
const names = {
  one: { none: "Brightness", unit: "Volume", prefixUnit: "Max price" },
  two: { none: "Age range", unit: "Humidity range", prefixUnit: "Price range" },
  three: { none: "Age groups", unit: "Discount tiers", prefixUnit: "Price tiers" },
}

const [thumbs, setThumbs] = useState("one") // or "two", "three"
const [values, setValues] = useState({ one: 50, two: [25, 75], three: [10, 40, 70] })
const [minStepsBetweenThumbs, setMinStepsBetweenThumbs] = useState(5) // with two or three thumbs
const [step, setStep] = useState("1") // or "5", "10", "25"; with one thumb
const [resetValue, setResetValue] = useState(true) // with one thumb
const [unit, setUnit] = useState("unit") // or "none", "prefixUnit"
const [marks, setMarks] = useState(false) // horizontal only
const [colors, setColors] = useState(false)
const [adornments, setAdornments] = useState(false) // horizontal only
const [tooltip, setTooltip] = useState(false)
const [orientation, setOrientation] = useState("horizontal") // or "vertical"
const [disabled, setDisabled] = useState(false)

const setValue = (value) => setValues({ ...values, [thumbs]: value })
// A small and a large letter at the ends size text
const name = adornments && thumbs === "one" ? "Text size" : names[thumbs][unit]
const text = (value) => (unit === "prefixUnit" ? "$" : "") + value + (unit === "unit" ? "%" : "")
const shared = {
  min: 0,
  max: 100,
  step: thumbs === "one" ? Number(step) : 1,
  marks: marks ? scaleMarks : undefined, // a vertical slider draws none
  // One hue: the fill in green and the track in a light tint of it
  trackColor: colors ? "#61C45433" : undefined,
  rangeColor: colors ? "#61C454" : undefined,
  // A small and a large letter at the ends, as Settings draws a text size slider; a vertical slider draws none
  startAdornment: adornments ? <span className="text-[15px]">A</span> : undefined,
  endAdornment: adornments ? <span className="text-[22px]">A</span> : undefined,
  disabled,
}

const desktop = {
  ...shared,
  label: tooltip ? (
    <Tooltip content="Drag to adjust, or type a value">
      <Tooltip.TriggerDecorator>{name}</Tooltip.TriggerDecorator>
    </Tooltip>
  ) : name,
  unit: unit === "unit" ? "%" : undefined,
  prefixUnit: unit === "prefixUnit" ? "$" : undefined,
  orientation,
}

// Desktop
<div style={orientation === "horizontal" ? { width: 300 } : undefined}>
  {thumbs === "one" ? (
    <Slider {...desktop} value={values.one} onChange={setValue} resetValue={resetValue ? 50 : undefined} />
  ) : (
    <Slider {...desktop} range value={values[thumbs]} onChange={setValue} minStepsBetweenThumbs={minStepsBetweenThumbs} />
  )}
</div>

// Phone: the group's title names the slider; one value ends the cell, a field the number is typed in, a range goes
// under the track, and marks show the scale in its place. The reset is a row of its own under the group. The phone
// slider is horizontal, with no tooltip.
const [typed, setTyped] = useState<string | null>(null) // the number while it is typed
const cancelTyped = useRef(false) // Escape keeps the value
const commitTyped = () => {
  const number = Number(typed?.trim() || NaN)
  // Whole and within the scale, as the slider's own field takes a typed number
  if (!cancelTyped.current && Number.isFinite(number)) setValue(Math.min(100, Math.max(0, Math.floor(number))))
  setTyped(null)
}

<FieldGroup title={name}>
  {thumbs === "one" && !marks ? (
    <div data-row className="flex min-h-[var(--field-row-min-height)] items-center gap-3 px-[var(--field-row-padding-inline)]">
      <Slider aria-label={name} {...shared} value={values.one} onChange={setValue} className="min-w-0 flex-1" />
      {/* The letters stand where the value would: Settings shows none beside them */}
      {!adornments && <label className={`min-w-[4ch] shrink-0 text-end text-[length:var(--field-row-label-font-size)] leading-[var(--field-row-label-line-height)] tabular-nums inline-flex items-center justify-end cursor-text ${disabled ? "text-[var(--mobile-label-tertiary,var(--color-text-disabled))]" : "text-secondary"}`}>
        {unit === "prefixUnit" && "$"}
        <input
          aria-label={`${name} value`}
          inputMode="numeric"
          enterKeyHint="done"
          className="min-w-[1ch] border-0 bg-transparent p-0 text-end tabular-nums [color:inherit] [font:inherit] outline-none disabled:cursor-default"
          style={{ width: `${Math.max(1, String(typed ?? values.one).length)}ch` }}
          value={typed ?? values.one}
          disabled={disabled}
          onFocus={(event) => { cancelTyped.current = false; setTyped(String(values.one)); event.currentTarget.select() }}
          onChange={(event) => setTyped(event.currentTarget.value)}
          onKeyDown={(event) => {
            if (event.key === "Escape") cancelTyped.current = true
            if (event.key === "Enter" || event.key === "Escape") event.currentTarget.blur()
          }}
          onBlur={commitTyped}
        />
        {unit === "unit" && "%"}
      </label>}
    </div>
  ) : (
    <div data-row className="flex flex-col px-[var(--field-row-padding-inline)] pb-1 [--slider-control-height:44px]">
      {thumbs === "one" ? (
        <Slider aria-label={name} {...shared} value={values.one} onChange={setValue} />
      ) : (
        <Slider range aria-label={name} {...shared} value={values[thumbs]} onChange={setValue} minStepsBetweenThumbs={minStepsBetweenThumbs} />
      )}
      {!marks && (
        <span className={`text-center text-[length:var(--field-row-description-font-size)] leading-[var(--field-row-description-line-height)] tabular-nums${disabled ? " text-[var(--mobile-label-tertiary,var(--color-text-disabled))]" : ""}`}>{values[thumbs].map(text).join(" – ")}</span>
      )}
    </div>
  )}
</FieldGroup>
{thumbs === "one" && resetValue && (
